// ListAutoPaging, List sonuçlarını next_cursor ile tüm sayfalar boyunca tek tek dolaşır.
//
//	it := client.Segments.ListAutoPaging(ctx, …)
//	for it.Next() {
//		item := it.Current()
//	}
//	if err := it.Err(); err != nil { … }
func (s *SegmentsService) ListAutoPaging(ctx context.Context, params *SegmentsListParams, opts ...RequestOption) *Iter[Segment] {
	base := SegmentsListParams{}
	if params != nil {
		base = *params
	}
	return newIter(ctx, deref(base.Cursor), func(ctx context.Context, cursor string) ([]Segment, string, bool, error) {
		p := base
		p.Cursor = nil
		if cursor != "" {
			p.Cursor = &cursor
		}
		page, err := s.List(ctx, &p, opts...)
		if err != nil {
			return nil, "", false, err
		}
		return page.Data, deref(page.NextCursor), page.HasMore, nil
	})
}

